    launcher_ui_ce_network_desc: { en: 'Executed code can connect to external network destinations.', ar: 'يمكن للتعليمات البرمجية المنفذة الاتصال بوجهات شبكة خارجية.', de: 'Ausgeführter Code kann externe Netzwerkziele erreichen.', es: 'El código ejecutado puede conectarse a destinos de red externos.', fr: 'Le code exécuté peut se connecter à des destinations réseau externes.', hi: 'निष्पादित कोड बाहरी नेटवर्क गंतव्यों से कनेक्ट हो सकता है।', it: 'Il codice eseguito può connettersi a destinazioni di rete esterne.', ja: '実行されたコードが外部ネットワーク宛先へ接続できます。', pt: 'O código executado pode ligar-se a destinos de rede externos.', ru: 'Выполняемый код сможет подключаться к внешним сетевым ресурсам.', zh: '执行的代码可以连接到外部网络目标。' },
    launcher_ui_ce_allow_pip: { en: 'Allow requested pip packages', ar: 'السماح بحزم pip المطلوبة', de: 'Angeforderte pip-Pakete zulassen', es: 'Permitir paquetes pip solicitados', fr: 'Autoriser les paquets pip demandés', hi: 'अनुरोधित pip पैकेज की अनुमति दें', it: 'Consenti i pacchetti pip richiesti', ja: '要求された pip パッケージを許可', pt: 'Permitir pacotes pip pedidos', ru: 'Разрешить запрошенные пакеты pip', zh: '允许请求的 pip 软件包' },
    launcher_ui_ce_pip_desc: { en: 'Models can install additional packages from configured indexes.', ar: 'يمكن للنماذج تثبيت حزم إضافية من الفهارس المُهيأة.', de: 'Modelle können zusätzliche Pakete aus konfigurierten Indizes installieren.', es: 'Los modelos pueden instalar paquetes adicionales desde los índices configurados.', fr: 'Les modèles peuvent installer des paquets supplémentaires depuis les index configurés.', hi: 'मॉडल कॉन्फ़िगर किए गए इंडेक्स से अतिरिक्त पैकेज इंस्टॉल कर सकते हैं।', it: 'I modelli possono installare pacchetti aggiuntivi dagli indici configurati.', ja: 'モデルが構成済みインデックスから追加パッケージをインストールできます。', pt: 'Os modelos podem instalar pacotes adicionais a partir dos índices configurados.', ru: 'Модели смогут устанавливать дополнительные пакеты из настроенных индексов.', zh: '模型可以从已配置的索引安装其他软件包。' },
