    launcher_ui_ce_edit_title: { en: 'Edit Code Execution service', ar: 'تعديل خدمة تنفيذ التعليمات البرمجية', de: 'Codeausführungsdienst bearbeiten', es: 'Editar servicio de ejecución de código', fr: 'Modifier le service d’exécution de code', hi: 'कोड निष्पादन सेवा संपादित करें', it: 'Modifica servizio di esecuzione del codice', ja: 'コード実行サービスを編集', pt: 'Editar serviço de execução de código', ru: 'Изменить службу выполнения кода', zh: '编辑代码执行服务' },
    launcher_ui_ce_recreate_desc: { en: 'Changes are applied by recreating this service when it is running.', ar: 'تُطبّق التغييرات بإعادة إنشاء هذه الخدمة عندما تكون قيد التشغيل.', de: 'Änderungen werden bei laufendem Dienst durch dessen Neuerstellung angewendet.', es: 'Los cambios se aplican recreando el servicio cuando está en ejecución.', fr: 'Les modifications sont appliquées en recréant le service lorsqu’il est en cours d’exécution.', hi: 'सेवा चल रही हो तो उसे फिर से बनाकर परिवर्तन लागू किए जाते हैं।', it: 'Quando il servizio è in esecuzione, le modifiche vengono applicate ricreandolo.', ja: '実行中の場合、サービスを再作成して変更を適用します。', pt: 'Quando o serviço está em execução, as alterações são aplicadas recriando-o.', ru: 'Если служба запущена, изменения применяются путём её пересоздания.', zh: '服务运行时，将通过重新创建服务来应用更改。' },
