    launcher_ui_ce_delete_warning: { en: 'Select Confirm delete to remove containers, sessions, settings, and the Redis volume.', ar: 'اختر «تأكيد الحذف» لإزالة الحاويات والجلسات والإعدادات ووحدة تخزين Redis.', de: 'Wählen Sie „Löschen bestätigen“, um Container, Sitzungen, Einstellungen und das Redis-Volume zu entfernen.', es: 'Selecciona «Confirmar eliminación» para quitar contenedores, sesiones, ajustes y el volumen de Redis.', fr: 'Sélectionnez « Confirmer la suppression » pour retirer les conteneurs, sessions, réglages et le volume Redis.', hi: 'कंटेनर, सत्र, सेटिंग और Redis वॉल्यूम हटाने के लिए “हटाने की पुष्टि करें” चुनें।', it: 'Seleziona «Conferma eliminazione» per rimuovere container, sessioni, impostazioni e volume Redis.', ja: 'コンテナ、セッション、設定、Redis ボリュームを削除するには「削除を確定」を選択してください。', pt: 'Selecione «Confirmar eliminação» para remover contentores, sessões, definições e o volume Redis.', ru: 'Выберите «Подтвердить удаление», чтобы удалить контейнеры, сеансы, настройки и том Redis.', zh: '选择“确认删除”以移除容器、会话、设置和 Redis 卷。' },
