    launcher_ui_choose_a_regular_file: { en: 'Choose a regular file.', ar: 'اختر ملفًا عاديًا.', de: 'Wählen Sie eine reguläre Datei.', es: 'Elige un archivo normal.', fr: 'Choisissez un fichier ordinaire.', hi: 'एक सामान्य फ़ाइल चुनें।', it: 'Scegli un file normale.', ja: '通常のファイルを選択してください。', pt: 'Escolha um ficheiro normal.', ru: 'Выберите обычный файл.', zh: '请选择普通文件。' },
