    launcher_ui_file_missing_or_unreadable: { en: 'File does not exist or cannot be read.', ar: 'الملف غير موجود أو لا يمكن قراءته.', de: 'Die Datei ist nicht vorhanden oder kann nicht gelesen werden.', es: 'El archivo no existe o no se puede leer.', fr: 'Le fichier n’existe pas ou ne peut pas être lu.', hi: 'फ़ाइल मौजूद नहीं है या पढ़ी नहीं जा सकती।', it: 'Il file non esiste o non può essere letto.', ja: 'ファイルが存在しないか、読み取れません。', pt: 'O ficheiro não existe ou não pode ser lido.', ru: 'Файл не существует или недоступен для чтения.', zh: '文件不存在或无法读取。' },
