    launcher_ui_value1_must_be_1_mb_or_smaller: { en: '{value1} must be 1 MB or smaller.', ar: 'يجب ألا يتجاوز حجم {value1} ‏1 ميغابايت.', de: '{value1} darf höchstens 1 MB groß sein.', es: '{value1} debe tener un tamaño máximo de 1 MB.', fr: '{value1} doit faire 1 Mo ou moins.', hi: '{value1} का आकार 1 MB या उससे कम होना चाहिए।', it: '{value1} deve avere dimensioni pari o inferiori a 1 MB.', ja: '{value1} は 1 MB 以下にしてください。', pt: '{value1} tem de ter 1 MB ou menos.', ru: 'Размер «{value1}» не должен превышать 1 МБ.', zh: '{value1} 必须不超过 1 MB。' },
    launcher_ui_enable_proxy_before_starting: { en: 'Enable the launcher proxy before starting it.', ar: 'مكّن وكيل المشغّل قبل تشغيله.', de: 'Aktivieren Sie den Launcher-Proxy, bevor Sie ihn starten.', es: 'Activa el proxy del iniciador antes de iniciarlo.', fr: 'Activez le proxy du lanceur avant de le démarrer.', hi: 'लॉन्चर प्रॉक्सी शुरू करने से पहले उसे सक्षम करें।', it: 'Abilita il proxy del launcher prima di avviarlo.', ja: '起動する前にランチャープロキシを有効にしてください。', pt: 'Ative o proxy do iniciador antes de o iniciar.', ru: 'Включите прокси средства запуска перед запуском.', zh: '启动前请先启用启动器代理。' },
