    launcher_ui_value1_integer_minimum_value2: { en: '{value1} must be an integer of at least {value2}.', ar: 'يجب أن تكون قيمة {value1} عددًا صحيحًا لا يقل عن {value2}.', de: '{value1} muss eine ganze Zahl von mindestens {value2} sein.', es: '{value1} debe ser un número entero de al menos {value2}.', fr: '{value1} doit être un entier supérieur ou égal à {value2}.', hi: '{value1} कम से कम {value2} का पूर्णांक होना चाहिए।', it: '{value1} deve essere un numero intero almeno pari a {value2}.', ja: '{value1} は {value2} 以上の整数にしてください。', pt: '{value1} tem de ser um número inteiro igual ou superior a {value2}.', ru: 'Значение «{value1}» должно быть целым числом не меньше {value2}.', zh: '{value1} 必须是至少为 {value2} 的整数。' },
