    launcher_ui_value1_must_use_yyyy_mm_dd: { en: '{value1} must use YYYY-MM-DD.', ar: 'يجب أن تستخدم قيمة {value1} التنسيق YYYY-MM-DD.', de: '{value1} muss das Format YYYY-MM-DD verwenden.', es: '{value1} debe usar el formato YYYY-MM-DD.', fr: '{value1} doit utiliser le format YYYY-MM-DD.', hi: '{value1} में YYYY-MM-DD प्रारूप का उपयोग करें।', it: '{value1} deve usare il formato YYYY-MM-DD.', ja: '{value1} は YYYY-MM-DD 形式で入力してください。', pt: '{value1} tem de utilizar o formato YYYY-MM-DD.', ru: 'Для «{value1}» используйте формат YYYY-MM-DD.', zh: '{value1} 必须使用 YYYY-MM-DD 格式。' },
    launcher_ui_value1_valid_date_yyyy_mm_dd: { en: '{value1} must be a valid date using YYYY-MM-DD.', ar: 'يجب أن تكون قيمة {value1} تاريخًا صالحًا بالتنسيق YYYY-MM-DD.', de: '{value1} muss ein gültiges Datum im Format YYYY-MM-DD sein.', es: '{value1} debe ser una fecha válida con el formato YYYY-MM-DD.', fr: '{value1} doit être une date valide au format YYYY-MM-DD.', hi: '{value1} YYYY-MM-DD प्रारूप में मान्य तारीख होनी चाहिए।', it: '{value1} deve essere una data valida nel formato YYYY-MM-DD.', ja: '{value1} には YYYY-MM-DD 形式の有効な日付を入力してください。', pt: '{value1} tem de ser uma data válida no formato YYYY-MM-DD.', ru: 'Значение «{value1}» должно быть допустимой датой в формате YYYY-MM-DD.', zh: '{value1} 必须是使用 YYYY-MM-DD 格式的有效日期。' },
    launcher_ui_created_after_not_later_than_before: { en: 'Created after must not be later than created before.', ar: 'يجب ألا يكون تاريخ «تم الإنشاء بعد» لاحقًا لتاريخ «تم الإنشاء قبل».', de: '„Erstellt nach“ darf nicht später als „Erstellt vor“ sein.', es: 'La fecha «Creado después de» no puede ser posterior a «Creado antes de».', fr: 'La date « Créé après » ne doit pas être postérieure à « Créé avant ».', hi: '“इसके बाद बनाया गया” तारीख “इससे पहले बनाया गया” तारीख से बाद की नहीं हो सकती।', it: 'La data “Creato dopo” non può essere successiva a “Creato prima”.', ja: '「作成日（以降）」は「作成日（以前）」より後の日付にできません。', pt: 'A data «Criado depois de» não pode ser posterior a «Criado antes de».', ru: 'Дата «Создано после» не должна быть позже даты «Создано до».', zh: '“创建时间晚于”不能晚于“创建时间早于”。' },
    launcher_ui_another_server_operation_active: { en: 'Another Omlorix server operation is already active.', ar: 'هناك عملية أخرى لخادم Omlorix نشطة بالفعل.', de: 'Ein anderer Omlorix-Servervorgang ist bereits aktiv.', es: 'Ya hay otra operación del servidor Omlorix activa.', fr: 'Une autre opération du serveur Omlorix est déjà active.', hi: 'एक अन्य Omlorix सर्वर ऑपरेशन पहले से सक्रिय है।', it: 'È già attiva un’altra operazione del server Omlorix.', ja: '別の Omlorix サーバー操作がすでに実行中です。', pt: 'Já está ativa outra operação do servidor Omlorix.', ru: 'Другая операция сервера Omlorix уже выполняется.', zh: '另一项 Omlorix 服务器操作已在进行。' },
    launcher_ui_invalid_legacy_update_channel_value1: { en: 'Invalid legacy update channel {value1}.', ar: 'قناة التحديث القديمة {value1} غير صالحة.', de: 'Ungültiger älterer Updatekanal {value1}.', es: 'El canal de actualización antiguo {value1} no es válido.', fr: 'L’ancien canal de mise à jour {value1} n’est pas valide.', hi: 'पुराना अपडेट चैनल {value1} अमान्य है।', it: 'Il canale di aggiornamento precedente {value1} non è valido.', ja: '従来の更新チャンネル {value1} は無効です。', pt: 'O canal de atualização antigo {value1} é inválido.', ru: 'Недопустимый прежний канал обновления {value1}.', zh: '旧版更新通道 {value1} 无效。' },
    launcher_ui_choose_supported_service_action: { en: 'Choose a supported service action.', ar: 'اختر إجراء خدمة مدعومًا.', de: 'Wählen Sie eine unterstützte Dienstaktion.', es: 'Elige una acción de servicio compatible.', fr: 'Choisissez une action de service prise en charge.', hi: 'समर्थित सेवा कार्रवाई चुनें।', it: 'Scegli un’azione di servizio supportata.', ja: 'サポートされているサービス操作を選択してください。', pt: 'Escolha uma ação de serviço suportada.', ru: 'Выберите поддерживаемое действие службы.', zh: '请选择受支持的服务操作。' },
