  for (const [key, entry] of Object.entries(managerInputErrorCatalog)) {
    launcherTranslations.source[key] = entry.en;
    for (const language of Object.keys(launcherTranslations.locales)) {
      launcherTranslations.locales[language][key] = entry[language];
    }
  }

  // These failures are safe, purpose-written manager messages rather than raw
