    launcher_ui_windows_proxy_operation_cancelled_or_failed: { en: 'The Windows proxy service operation was cancelled or failed.', ar: 'أُلغيت عملية خدمة وكيل Windows أو فشلت.', de: 'Der Vorgang für den Windows-Proxy-Dienst wurde abgebrochen oder ist fehlgeschlagen.', es: 'La operación del servicio de proxy de Windows se canceló o produjo un error.', fr: 'L’opération du service proxy Windows a été annulée ou a échoué.', hi: 'Windows प्रॉक्सी सेवा की कार्रवाई रद्द कर दी गई या विफल रही।', it: 'L’operazione del servizio proxy di Windows è stata annullata o non è riuscita.', ja: 'Windows プロキシサービスの操作がキャンセルされたか、失敗しました。', pt: 'A operação do serviço proxy do Windows foi cancelada ou falhou.', ru: 'Операция службы прокси Windows была отменена или завершилась ошибкой.', zh: 'Windows 代理服务操作已取消或失败。' },
