    launcher_ui_attach_backend_to_launcher_network_failed: { en: 'Could not attach the running Omlorix backend to the launcher services network.', ar: 'تعذر ربط الواجهة الخلفية العاملة لـ Omlorix بشبكة خدمات المشغّل.', de: 'Das laufende Omlorix-Backend konnte nicht mit dem Netzwerk der Launcher-Dienste verbunden werden.', es: 'No se pudo conectar el backend de Omlorix en ejecución a la red de servicios del iniciador.', fr: 'Impossible de connecter le backend Omlorix actif au réseau des services du lanceur.', hi: 'चल रहे Omlorix बैकएंड को लॉन्चर सेवा नेटवर्क से नहीं जोड़ा जा सका।', it: 'Impossibile collegare il backend Omlorix in esecuzione alla rete dei servizi del launcher.', ja: '実行中の Omlorix バックエンドをランチャーサービスネットワークに接続できませんでした。', pt: 'Não foi possível ligar o backend do Omlorix em execução à rede de serviços do iniciador.', ru: 'Не удалось подключить работающий бэкенд Omlorix к сети служб программы запуска.', zh: '无法将正在运行的 Omlorix 后端连接到启动器服务网络。' },
