    launcher_ui_proxy_authentication_credential_unavailable: { en: 'The launcher proxy authentication credential is unavailable.', ar: 'بيانات اعتماد مصادقة وكيل المشغّل غير متاحة.', de: 'Die Authentifizierungsdaten des Launcher-Proxys sind nicht verfügbar.', es: 'La credencial de autenticación del proxy del iniciador no está disponible.', fr: 'L’identifiant d’authentification du proxy du lanceur est indisponible.', hi: 'लॉन्चर प्रॉक्सी प्रमाणीकरण क्रेडेंशियल उपलब्ध नहीं है।', it: 'La credenziale di autenticazione del proxy del launcher non è disponibile.', ja: 'ランチャープロキシの認証資格情報を利用できません。', pt: 'A credencial de autenticação do proxy do iniciador não está disponível.', ru: 'Учётные данные аутентификации прокси программы запуска недоступны.', zh: '启动器代理身份验证凭据不可用。' },
