    launcher_ui_visitor_ip_verification_failed: { en: 'End-to-end visitor IP and scheme verification failed.', ar: 'فشل التحقق الشامل من عنوان IP للزائر والمخطط.', de: 'Die End-to-End-Prüfung der Besucher-IP und des Schemas ist fehlgeschlagen.', es: 'Error en la verificación integral de la IP del visitante y del esquema.', fr: 'La vérification de bout en bout de l’IP visiteur et du schéma a échoué.', hi: 'विज़िटर IP और स्कीम का एंड-टू-एंड सत्यापन विफल रहा।', it: 'La verifica end-to-end dell’IP del visitatore e dello schema non è riuscita.', ja: '訪問者 IP とスキームのエンドツーエンド検証に失敗しました。', pt: 'A verificação ponto a ponto do IP do visitante e do esquema falhou.', ru: 'Не удалось выполнить сквозную проверку IP-адреса посетителя и схемы.', zh: '访客 IP 和协议的端到端验证失败。' },
    launcher_ui_visitor_ip_restore_after_failure: { en: 'Visitor IP settings could not be applied and verified. The previous configuration was restored.', ar: 'تعذر تطبيق إعدادات عنوان IP للزائر والتحقق منها. تمت استعادة الإعدادات السابقة.', de: 'Die Besucher-IP-Einstellungen konnten nicht angewendet und überprüft werden. Die vorherige Konfiguration wurde wiederhergestellt.', es: 'No se pudo aplicar ni verificar la configuración de IP de visitantes. Se restauró la configuración anterior.', fr: 'Les paramètres d’IP visiteurs n’ont pas pu être appliqués et vérifiés. La configuration précédente a été restaurée.', hi: 'विज़िटर IP सेटिंग लागू और सत्यापित नहीं की जा सकीं। पिछला कॉन्फ़िगरेशन पुनर्स्थापित कर दिया गया।', it: 'Non è stato possibile applicare e verificare le impostazioni IP dei visitatori. La configurazione precedente è stata ripristinata.', ja: '訪問者 IP 設定を適用して検証できませんでした。以前の構成を復元しました。', pt: 'Não foi possível aplicar e verificar as definições de IP dos visitantes. A configuração anterior foi restaurada.', ru: 'Не удалось применить и проверить настройки IP-адресов посетителей. Предыдущая конфигурация восстановлена.', zh: '无法应用并验证访客 IP 设置。已恢复之前的配置。' },
    launcher_ui_launcher_updater_not_configured: { en: 'Launcher updater is not configured.', ar: 'أداة تحديث المشغّل غير مهيأة.', de: 'Die Launcher-Aktualisierung ist nicht konfiguriert.', es: 'El actualizador del iniciador no está configurado.', fr: 'Le programme de mise à jour du lanceur n’est pas configuré.', hi: 'लॉन्चर अपडेटर कॉन्फ़िगर नहीं किया गया है।', it: 'Il programma di aggiornamento del launcher non è configurato.', ja: 'ランチャーアップデーターが構成されていません。', pt: 'O atualizador do iniciador não está configurado.', ru: 'Средство обновления программы запуска не настроено.', zh: '启动器更新程序尚未配置。' },
    launcher_ui_launcher_updater_message_box_required: { en: 'Launcher updater requires a message box function.', ar: 'تتطلب أداة تحديث المشغّل دالة لعرض مربع رسالة.', de: 'Die Launcher-Aktualisierung benötigt eine Meldungsdialog-Funktion.', es: 'El actualizador del iniciador requiere una función de cuadro de mensaje.', fr: 'Le programme de mise à jour du lanceur nécessite une fonction de boîte de dialogue.', hi: 'लॉन्चर अपडेटर के लिए संदेश बॉक्स फ़ंक्शन आवश्यक है।', it: 'Il programma di aggiornamento del launcher richiede una funzione per la finestra di messaggio.', ja: 'ランチャーアップデーターにはメッセージボックス関数が必要です。', pt: 'O atualizador do iniciador requer uma função de caixa de mensagem.', ru: 'Средству обновления программы запуска требуется функция окна сообщения.', zh: '启动器更新程序需要消息框函数。' },
